import {quizConfig as config} from './quiz-config.js';
import {shuffle, freshProgress, isMastered, isDue, recordAnswer, chooseQuestions, validProgress} from './engine.js';

const $ = s => document.querySelector(s);
const main = $('#main');
const KEY = config.storageKey;
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl = u => { try {const v=new URL(u); return v.protocol === 'https:' || v.protocol === 'http:' ? esc(v.href) : '#';} catch{return '#';} };

// Local data links and external project links both pass through this protocol check.
const safeHref = path => {try{const url=new URL(path,location.href);return ['https:','http:'].includes(url.protocol)?esc(url.href):'#';}catch{return '#';}};
function releaseLinks(){return `<a href="${safeHref(config.links.source)}" target="_blank" rel="noopener noreferrer">View source</a><a href="${safeHref(config.links.dataDownload)}" download="questions.json">Download questions</a><a href="${safeHref(config.links.corrections)}" target="_blank" rel="noopener noreferrer">Report a correction</a>`;}
function applyConfig(){
  $('#brand-name').textContent=config.brand.wordmark || config.brand.name;
  $('.wordmark').setAttribute('aria-label',config.brand.name+' home');
  $('#brand-subtitle').textContent=config.brand.subtitle;
  $('.footer-brand').textContent=(config.brand.wordmark || config.brand.name)+'.';
  $('#brand-tagline').textContent=config.brand.tagline;
  $('#edition-label').textContent='Content reviewed '+config.edition.label;
  $('#release-links').innerHTML=releaseLinks();
  $('meta[name="description"]').content=config.brand.description;
  $('meta[name="theme-color"]').content=config.brand.themeColor;
  $('meta[property="og:title"]').content=config.brand.name+' — '+config.brand.subtitle;
  $('meta[property="og:description"]').content=config.brand.description;
}

const icons = {
  process:'<path d="M4 7h9m-3-3 3 3-3 3M20 17h-9m3-3-3 3 3 3M5 13v7h5M19 11V4h-5"/>',
  power:'<path d="M3 9h18L12 3 3 9ZM5 20h14M7 11v6m5-6v6m5-6v6M3 22h18"/>',
  enacted:'<path d="M6 3h9l3 3v15H6V3Zm8 0v5h4M9 14l2 2 4-5"/>',
  pending:'<rect x="4" y="4" width="16" height="16" rx="2"/><path d="M8 9h8M8 13h5M8 17h3M15 15l3 3m0-3-3 3"/>',
  history:'<path d="M4 10a8 8 0 1 1 0 5M4 4v6h6M12 7v6l4 2"/>',
  people:'<circle cx="12" cy="7" r="3"/><path d="M6 21v-3a6 6 0 0 1 12 0v3M4 8a3 3 0 0 0 0 6M20 8a3 3 0 0 1 0 6M2 21v-3m20 3v-3"/>'
};
const modules = config.topics;
const categoryIds = modules.map(m => m.id);
const mod = id => modules.find(m=>m.id===id);
let bank=[], profiles=[], portraitIds=[], progress=freshProgress(), view='home', roundSize=config.defaultRoundSize || config.roundSizes[0], guideTab='people', guideQuery='', lastResult=null, storageAvailable=true;
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(progress));}catch{storageAvailable=false;toast('Browser storage is unavailable. Keep this tab open or export your progress.');}}
function mount(html, name, {scroll=true}={}) {main.innerHTML=html;view=name;document.querySelectorAll('nav [data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===name));if(scroll){window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});}document.title=`${name==='quiz'?'Your briefing':name==='guide'?'Field guide':name==='progress'?'Your progress':config.brand.subtitle} · ${config.brand.name}`;}
function sourcesHtml(sources){return `<ul class="source-list">${sources.map(s=>`<li><a href="${safeUrl(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} →</a></li>`).join('')}</ul>`;}
function dueQuestions(){return bank.filter(q=>isDue(progress.questions[q.id]));}
function topicStats(id){const qs=bank.filter(q=>q.category===id);return {total:qs.length,seen:qs.filter(q=>progress.questions[q.id]).length,mastered:qs.filter(q=>isMastered(progress.questions[q.id])).length};}
function chamberArt(){let seats='';for(let row=0;row<5;row++){let n=11+row*4,r=48+row*20;for(let j=0;j<n;j++){const t=Math.PI+(j+.5)/n*Math.PI;const x=180+Math.cos(t)*r,y=155+Math.sin(t)*r;seats+=`<rect x="${x-4}" y="${y-4}" width="8" height="8" rx="2" fill="${(j+row*3)%9===0?'#db4e29':row%2?'#7d9071':'#a1b090'}" transform="rotate(${t*180/Math.PI+90} ${x} ${y})"/>`;}}return `<svg class="chamber-art" viewBox="20 10 320 165" role="img" aria-label="Illustration of a congressional chamber; decorative, not a seat count">${seats}<path d="M155 150a25 25 0 0 1 50 0" fill="none" stroke="#445c41" stroke-width="2"/><rect x="170" y="144" width="20" height="9" rx="2" fill="#445c41"/><path d="M135 166h90" stroke="#a9b49d"/></svg>`;}
function home(){const due=dueQuestions().length;const seen=Object.keys(progress.questions).length;const resume=progress.session?`<div class="resume"><p><strong>Your briefing is saved.</strong> <small>${Object.keys(progress.session.answers).length} of ${progress.session.queue.length} answered</small></p><button class="btn secondary" data-action="resume">Continue →</button></div>`:'';mount(`${resume}<section class="hero"><div><span class="eyebrow orange"><span class="line"></span> ${esc(config.brand.eyebrow)}</span><h1>${config.brand.headline.map((line,i)=>i===config.brand.headline.length-1?`<em>${esc(line)}</em>`:esc(line)).join('<br>')}</h1><p>${esc(config.brand.intro)}</p><div class="actions"><button class="btn primary" data-action="${seen?'mixed':'placement'}">${seen?'Start a briefing':'Find your starting point'} <span>→</span></button><button class="text-btn" data-nav="guide">Explore the field guide</button></div><div class="hero-note"><span>${bank.length} source-linked questions</span><span>No time pressure</span><span>Made for learning</span></div></div><div class="hero-art"><div class="art-label"><span>${esc(config.brand.artLabel)}</span><span>${esc(config.brand.artEdition)}</span></div>${config.brand.showChamberArt?chamberArt():'<div class="quiz-art-mark" aria-hidden="true">?</div>'}<div class="art-bottom"><div><strong>${esc(config.brand.artTitle)}</strong><br><span>${esc(config.brand.artDescription)}</span></div><div class="art-stamp">${config.brand.artStamp.map(esc).join('<br>')}</div></div></div></section><section class="quickbar" aria-label="Start a mixed round"><div class="quick-icon">→</div><div class="quick-copy"><h2>${esc(config.brand.quickTitle)}</h2><p>A fresh mix across ${modules.length} topic${modules.length===1?'':'s'}.</p></div><div class="segmented" role="group" aria-label="Questions per round">${config.roundSizes.map(n=>`<button data-size="${n}" class="${roundSize===n?'selected':''}" aria-pressed="${roundSize===n}">${n} Qs</button>`).join('')}</div><button class="btn" data-action="mixed">Start round →</button></section><section><div class="section-head"><div><span class="eyebrow orange">BUILD YOUR WORKING KNOWLEDGE</span><h2>${esc(config.brand.homeTitle)}</h2></div><p>${modules.length} topic${modules.length===1?'':'s'}. One connected picture.</p></div><div class="module-grid">${modules.map((m,i)=>{const st=topicStats(m.id);return `<button class="module-card" data-module="${m.id}"><div class="module-top"><span class="module-icon"><svg viewBox="0 0 24 24" aria-hidden="true">${icons[m.icon || m.id] || icons.process}</svg></span><span class="module-number">${String(i+1).padStart(2,'0')}</span></div><h3>${esc(m.title)}</h3><p>${esc(m.description)}</p><div class="module-foot"><span>${st.total} QUESTIONS${st.seen?' · '+st.seen+' SEEN':''}</span><span class="arrow-label">Open briefing →</span></div><div class="mini-track" aria-label="${st.mastered} of ${st.total} questions recalled twice"><i style="width:${st.total?st.mastered/st.total*100:0}%"></i></div></button>`;}).join('')}</div></section><div class="lower-banner"><p>${due?`<strong>${due} question${due!==1?'s':''} ready for another look.</strong> Make the ideas stick.`:'<strong>Every answer has a paper trail.</strong> Explanations and original sources, one click away.'}</p><button class="text-btn" data-action="${due?'review':'sources'}">${due?'Review what’s due →':'How we check the facts →'}</button></div>`,'home');}
function lesson(id){const m=mod(id);if(!m)return home();const st=topicStats(id);mount(`<section class="lesson-intro"><button class="back" data-nav="home">← All briefings</button><br><span class="eyebrow orange">${esc(m.short)}</span><h1>${esc(m.title)}</h1><p class="intro-text">${esc(m.intro)}</p><div class="lesson-objectives"><h2>IN THIS BRIEFING</h2><ul>${m.objectives.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></div><div class="actions"><button class="btn primary" data-start-topic="${m.id}">Start ${Math.min(roundSize,st.total)} questions →</button><div class="segmented" role="group" aria-label="Questions per round">${config.roundSizes.map(n=>`<button data-lesson-size="${n}" data-topic="${id}" class="${roundSize===n?'selected':''}" aria-pressed="${roundSize===n}">${n} Qs</button>`).join('')}</div></div><p class="lesson-meta">${st.total} questions in this topic · Untimed · Explanations after every answer</p></section>`,'lesson');}
function startSession(mode='mixed',category=null,count=roundSize){const questions=chooseQuestions(bank,progress.questions,{mode,category,count:mode==='placement'?config.placementCount:count,categoryOrder:categoryIds,placementCategories:config.placementCategories});if(!questions.length){toast('Nothing is due for review yet. Try a new briefing.');return;}progress.session={id:Date.now().toString(),mode,category,queue:questions.map(q=>q.id),index:0,answers:{},orders:Object.fromEntries(questions.map(q=>[q.id,shuffle([0,1,2,3])])),confidences:{},hints:{},selections:{}};save();quiz();}
function quiz({scroll=true}={}){const s=progress.session;if(!s)return home();const q=bank.find(q=>q.id===s.queue[s.index]);if(!q){progress.session=null;save();return home();}const a=s.answers[q.id];const order=s.orders[q.id];const selection=s.selections[q.id];const label=s.mode==='placement'?'Starting-point check':s.mode==='review'?'Review briefing':s.category?mod(s.category).short:'Mixed briefing';const isDone=s.index===s.queue.length-1;
  mount(`<section class="quiz-wrap"><div class="quiz-meta"><span>${esc(label)}</span><button class="text-btn" data-nav="home">Save & leave</button></div><div class="quiz-track" role="progressbar" aria-label="Round progress" aria-valuemin="0" aria-valuemax="${s.queue.length}" aria-valuenow="${Object.keys(s.answers).length}"><div style="width:${Object.keys(s.answers).length/s.queue.length*100}%"></div></div><div class="question-box"><div class="question-label"><span class="eyebrow orange">${esc(mod(q.category).short)} · ${s.index+1}/${s.queue.length}</span><span class="difficulty">${['','Foundations','Working knowledge','Applied judgment'][q.difficulty]}</span></div><h1 id="question-text">${esc(q.prompt)}</h1><div class="options" role="group" aria-labelledby="question-text">${order.map((oi,display)=>{const correct=!!a&&oi===q.correct;const wrong=!!a&&a.chosen===oi&&!a.correct;return `<button class="option ${selection===oi?'selected':''} ${correct?'correct':''} ${wrong?'wrong':''}" data-option="${oi}" aria-pressed="${selection===oi}" ${a?'disabled':''}><span class="option-letter">${String.fromCharCode(65+display)}</span><span>${esc(q.options[oi].text)}</span>${correct?'<span class="answer-mark" aria-label="Correct answer">✓</span>':wrong?'<span class="answer-mark" aria-label="Your answer was incorrect">×</span>':''}</button>`;}).join('')}</div>${!a?`<button class="hint-button" data-action="hint" aria-expanded="${!!s.hints[q.id]}">${s.hints[q.id]?'− Hide hint':'+ A little help?'}</button>${s.hints[q.id]?`<div class="hint">${esc(q.hint)}</div>`:''}<div class="confidence"><span>How sure are you? <span aria-label="optional">(optional)</span></span>${[['low','A guess'],['medium','Fairly sure'],['high','Very sure']].map(([v,t])=>`<button data-confidence="${v}" class="${s.confidences[q.id]===v?'selected':''}" aria-pressed="${s.confidences[q.id]===v}">${t}</button>`).join('')}</div>`:''}${a?`<section class="feedback" aria-live="polite" tabindex="-1" aria-label="Answer explanation"><div class="feedback-title ${a.correct?'':'missed'}">${a.skipped?'Here’s the key distinction.':a.correct?'You’ve got it.':'A useful distinction to remember.'}</div><p>${esc(q.options[q.correct].explanation)}</p>${!a.correct&&a.chosen!==null?`<p><strong>Your answer:</strong> ${esc(q.options[a.chosen].explanation)}</p>`:''}<div class="takeaway"><span>WHY IT MATTERS</span><p>${esc(q.takeaway)}</p></div><details><summary>Why the other answers don’t fit</summary>${order.filter(oi=>oi!==q.correct&&oi!==a.chosen).map(oi=>`<div class="alternative"><b>${esc(q.options[oi].text)}</b>${esc(q.options[oi].explanation)}</div>`).join('')}</details>${sourcesHtml(q.sources)}<p class="verified">Reviewed ${esc(q.asOf)} · Read the date and version in the question.</p></section>`:''}<div class="quiz-actions">${a?`<span class="keyboard-tip">Enter to continue</span><button class="btn primary" data-action="next">${isDone?'See your briefing':'Next question'} →</button>`:`<button class="text-btn" data-action="skip">I don’t know yet</button><button class="btn primary" data-action="check" ${selection===undefined?'disabled':''}>Check answer →</button>`}</div></div><p class="quiz-bottom">${storageAvailable?'Progress saves on this browser.':'Browser storage unavailable; export to keep your progress.'} <span class="keyboard-tip"> · Keys 1–4 select an answer; Enter checks it.</span></p></section>`,'quiz',{scroll});
}
function answer(skipped=false){const s=progress.session;if(!s)return;const q=bank.find(q=>q.id===s.queue[s.index]);if(s.answers[q.id])return;const chosen=skipped?null:s.selections[q.id];if(chosen===undefined)return;if(skipped)delete s.selections[q.id];const correct=chosen===q.correct;s.answers[q.id]={chosen,correct,skipped,confidence:s.confidences[q.id]||''};progress.questions[q.id]=recordAnswer(progress.questions[q.id],correct,s.confidences[q.id]||'',skipped);save();quiz({scroll:false});setTimeout(()=>{const feedback=$('.feedback');feedback?.focus({preventScroll:true});feedback?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'nearest'});},30);}
function next(){const s=progress.session;if(!s||!s.answers[s.queue[s.index]])return;if(s.index<s.queue.length-1){s.index++;save();quiz();}else finish();}
function finish(){const s=progress.session;if(!s)return;lastResult=structuredClone(s);progress.rounds.push({id:s.id,date:Date.now(),mode:s.mode,category:s.category,total:s.queue.length,right:Object.values(s.answers).filter(a=>a.correct).length});progress.rounds=progress.rounds.slice(-100);progress.session=null;save();results();}
function results(){if(!lastResult)return home();const s=lastResult;const right=Object.values(s.answers).filter(a=>a.correct).length;const missed=s.queue.filter(id=>!s.answers[id]?.correct);const weakest=modules.map(m=>({m,n:missed.filter(id=>bank.find(q=>q.id===id).category===m.id).length})).sort((a,b)=>b.n-a.n)[0];mount(`<section class="quiz-wrap"><div class="result-hero"><div><span class="eyebrow orange">BRIEFING COMPLETE</span><h1>${right===s.queue.length?esc(config.brand.perfectRoundTitle):right>=s.queue.length*.6?'Your working knowledge is growing.':'Good questions. Useful new ground.'}</h1><p>${s.mode==='placement'?'Your starting-point check is complete. Use the recommendation below, or choose any topic.':'The explanations are part of the learning. Revisit these ideas in a later round to make them stick.'}</p></div><div class="score-circle"><strong>${right}<small style="font-size:20px">/${s.queue.length}</small></strong><span>correct this round</span></div></div>${weakest?.n?`<div class="recommendation"><p><strong>A useful next briefing: ${weakest.m.title}.</strong> You have ${weakest.n} concept${weakest.n!==1?'s':''} from this round to revisit here.</p><button class="text-btn" data-module="${weakest.m.id}">Explore this topic →</button></div>`:`<div class="recommendation"><p><strong>Ready for the next layer.</strong> Try a longer mixed round or return later for spaced review.</p></div>`}<div class="actions"><button class="btn primary" data-action="mixed">Another briefing →</button>${missed.length?'<button class="btn secondary" data-action="review">Review missed concepts</button>':''}<button class="text-btn" data-nav="home">Back to topics</button></div><div class="section-head" style="margin-top:36px"><div><span class="eyebrow">YOUR PAPER TRAIL</span><h2>Review the round.</h2></div></div><div class="recap-list">${s.queue.map(id=>{const q=bank.find(q=>q.id===id),a=s.answers[id];return `<details class="recap-item"><summary><span class="result-dot ${a.correct?'':'missed'}">${a.correct?'✓':'↺'}</span>${esc(q.prompt)}</summary><p><strong>${esc(q.options[q.correct].text)}</strong></p><p>${esc(q.options[q.correct].explanation)}</p><p>${esc(q.takeaway)}</p>${sourcesHtml(q.sources)}</details>`;}).join('')}</div></section>`,'results');}
const glossary = config.glossary || [];
function profileCard(p){return `<article class="person"><div class="person-head">${portraitIds.includes(p.id)?`<img class="avatar" src="${safeHref(config.portraitsDirectory+'/'+p.id+'.jpg')}" alt="" loading="lazy">`:`<div class="avatar" aria-hidden="true">${esc(p.name.split(' ').filter(Boolean).map(x=>x[0]).slice(0,2).join(''))}</div>`}<div><h2>${esc(p.name)}</h2><span class="metadata">${esc(p.party)} · ${esc(p.state)} · ${esc(p.chamber)}</span></div></div><p class="focus">${esc(p.focus)}</p>${(p.record||[]).map(r=>`<div class="record"><time>${esc(r.date)}</time><p>${esc(r.text)}</p><a href="${safeUrl(r.url)}" target="_blank" rel="noopener noreferrer">Read the record →</a></div>`).join('')}</article>`;}
function filterProfiles(){const query=guideQuery.toLowerCase();return profiles.filter(p=>JSON.stringify([p.name,p.focus,p.state,p.chamber,p.record]).toLowerCase().includes(query));}
function guide({scroll=true}={}){const query=guideQuery.toLowerCase();const filtered=profiles.filter(p=>JSON.stringify([p.name,p.focus,p.state,p.chamber,p.record]).toLowerCase().includes(query));mount(`<section class="page-head"><span class="eyebrow orange">THE FIELD GUIDE</span><h1>${esc(config.guide.title)}</h1><p>${esc(config.guide.intro)}</p></section><div class="tabs" role="group" aria-label="Field guide section">${profiles.length?`<button class="${guideTab==='people'?'selected':''}" data-guide-tab="people" aria-pressed="${guideTab==='people'}">${esc(config.guide.profilesLabel)}</button>`:''}<button class="${guideTab==='terms'?'selected':''}" data-guide-tab="terms" aria-pressed="${guideTab==='terms'}">${esc(config.guide.termsLabel)}</button></div>${guideTab==='people'?`<label class="hidden" for="member-search">Search profiles</label><input class="search" id="member-search" type="search" placeholder="${esc(config.guide.searchPlaceholder)}" aria-label="Search profiles" value="${esc(guideQuery)}"><p class="list-summary">${filtered.length} profile${filtered.length===1?'':'s'} · Records reviewed ${esc(config.edition.label)}</p><div class="people-grid">${filtered.map(profileCard).join('')}</div>${!filtered.length?'<div class="empty">No matching profiles. Try a name or a broader term.</div>':''}`:`<div class="glossary">${glossary.map(([term,text,url])=>`<article><h2>${esc(term)}</h2><p>${esc(text)}</p><a href="${safeUrl(url)}" target="_blank" rel="noopener noreferrer">Source reference →</a></article>`).join('')}</div>`}`,'guide',{scroll});}
function progressPage(){const records=Object.values(progress.questions),seen=records.length,mastered=records.filter(isMastered).length,attempts=records.reduce((s,p)=>s+p.attempts,0),right=records.reduce((s,p)=>s+p.right,0);mount(`<section class="page-head"><span class="eyebrow orange">YOUR WORKING KNOWLEDGE</span><h1>Small briefings. Lasting understanding.</h1><p>Progress lives in this browser. Recalling a question correctly twice in a row marks it as reinforced; review brings it back over time.</p></section><div class="stats"><div class="stat"><strong>${seen}<small style="font-size:18px">/${bank.length}</small></strong><span>Questions explored</span></div><div class="stat"><strong>${mastered}</strong><span>Reinforced twice in a row</span></div><div class="stat"><strong>${dueQuestions().length}</strong><span>Ready for review</span></div><div class="stat"><strong>${attempts?Math.round(right/attempts*100)+'%':'—'}</strong><span>Accuracy across attempts</span></div></div><div class="actions"><button class="btn primary" data-action="${dueQuestions().length?'review':'mixed'}">${dueQuestions().length?'Start a review':'Start a briefing'} →</button><button class="btn secondary" data-action="placement">Recheck my starting point</button></div><div class="topic-progress">${modules.map(m=>{const s=topicStats(m.id);return `<div class="topic-row"><div class="row-top"><strong>${esc(m.title)}</strong><span>${s.mastered}/${s.total} reinforced</span></div><div class="mini-track"><i style="width:${s.total?s.mastered/s.total*100:0}%"></i></div><small>${s.seen} explored · ${s.total-s.seen} new</small></div>`;}).join('')}</div><div class="prose"><h2>Keep your progress.</h2><p>Completed answers and an unfinished round are saved automatically on this browser. Clearing site data removes them. Export a backup to move progress to another browser or device.</p><div class="actions"><button class="btn secondary" data-action="export">Export progress</button><button class="btn secondary" data-action="import">Import progress</button><button class="text-btn" data-action="reset">Reset progress</button></div><input id="import-file" type="file" accept="application/json,.json" class="hidden"><p class="note" style="margin-top:20px">Review intervals grow after correct answers: 1, 3, 7, 14, then 30 days. Missed or skipped questions stay available for review. This is a learning aid, not a measure of professional competence.</p></div>`,'progress');}
function sourcesPage(){mount(`${config.aboutHtml}<div class="prose"><h2>Open the source</h2><p>The code and original educational content are available under the MIT license. You can copy the app, adapt the questions, or make a quiz on a new subject. Keep the copyright and license notices, and check the separate attribution for third-party material.</p><div class="actions">${releaseLinks()}</div><p><a href="${safeHref(config.links.sourceDownload)}">Download the complete source package</a>, including the question bank, research notes, attribution, and validation checks.</p><h2>Your data</h2><p>Your answers and progress stay in this browser’s local storage. There is no quiz account or analytics service in the application. The hosting provider may process normal web request logs. Source links open external websites.</p><p>To move your progress to a new browser or domain, export it from Progress and import it on the new site.</p></div>`,'sources');}
function navigate(where){if(where==='home')home();else if(where==='guide')guide();else if(where==='progress')progressPage();else if(where==='sources')sourcesPage();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.nav){navigate(b.dataset.nav);return;}if(b.dataset.module){lesson(b.dataset.module);return;}if(b.dataset.startTopic){startSession('topic',b.dataset.startTopic);return;}if(b.dataset.size){roundSize=Number(b.dataset.size);home();return;}if(b.dataset.lessonSize){roundSize=Number(b.dataset.lessonSize);lesson(b.dataset.topic);return;}if(b.dataset.guideTab){guideTab=b.dataset.guideTab;guide();return;}if(b.dataset.option!==undefined){const s=progress.session;if(!s||s.answers[s.queue[s.index]])return;s.selections[s.queue[s.index]]=Number(b.dataset.option);save();quiz({scroll:false});$(`[data-option="${b.dataset.option}"]`)?.focus({preventScroll:true});return;}if(b.dataset.confidence){const s=progress.session;if(!s||s.answers[s.queue[s.index]])return;s.confidences[s.queue[s.index]]=b.dataset.confidence;save();quiz({scroll:false});$(`[data-confidence="${b.dataset.confidence}"]`)?.focus({preventScroll:true});return;}const action=b.dataset.action;if(!action)return;
  if(action==='mixed')startSession();else if(action==='placement')startSession('placement');else if(action==='review')startSession('review');else if(action==='resume')quiz();else if(action==='hint'){const s=progress.session;if(!s)return;s.hints[s.queue[s.index]]=!s.hints[s.queue[s.index]];save();quiz({scroll:false});$('.hint-button')?.focus({preventScroll:true});}else if(action==='check')answer();else if(action==='skip')answer(true);else if(action==='next')next();else if(action==='sources')sourcesPage();else if(action==='reset')$('#reset-dialog').showModal();else if(action==='export'){const data=JSON.stringify(progress,null,2);const url=URL.createObjectURL(new Blob([data],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=config.progressFilename || 'quiz-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Progress exported.');}else if(action==='import')$('#import-file').click();
});
document.addEventListener('input',e=>{if(e.target.id==='member-search'){guideQuery=e.target.value;const filtered=filterProfiles();$('.people-grid').innerHTML=filtered.map(profileCard).join('')||'<div class="empty">No matching profiles. Try a name or a broader term.</div>';$('.list-summary').textContent=`${filtered.length} profile${filtered.length===1?'':'s'} · Records reviewed ${config.edition.label}`;}});
document.addEventListener('change',async e=>{if(e.target.id!=='import-file')return;const f=e.target.files?.[0];if(!f)return;if(f.size>2000000){toast('That file is too large. Choose a quiz progress export.');return;}try{const value=JSON.parse(await f.text());if(!validProgress(value,new Set(bank.map(q=>q.id)),{categories:categoryIds}))throw new Error();progress={version:1,questions:value.questions,rounds:value.rounds.slice(-100),session:value.session||null};save();progressPage();toast('Progress imported.');}catch{toast('This is not a compatible quiz progress file. Your progress is unchanged.');}});
$('#cancel-reset').addEventListener('click',()=>$('#reset-dialog').close());$('#confirm-reset').addEventListener('click',()=>{progress=freshProgress();lastResult=null;save();$('#reset-dialog').close();progressPage();toast('Progress reset.');});
document.addEventListener('keydown',e=>{if(view!=='quiz'||e.ctrlKey||e.altKey||e.metaKey||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;const s=progress.session;if(!s)return;const a=s.answers[s.queue[s.index]];if(/^[1-4]$/.test(e.key)&&!a){e.preventDefault();$(`[data-option="${s.orders[s.queue[s.index]][Number(e.key)-1]}"]`)?.click();}else if(e.key==='Enter'&&(e.target.closest('[data-option],[data-confidence]')||!['BUTTON','SUMMARY','A'].includes(e.target.tagName))){e.preventDefault();if(a)next();else answer();}});
async function readJson(path, optional=false){
  if(!path)return [];
  const response=await fetch(path);
  if(!response.ok){if(optional)return [];throw new Error('Question bank unavailable');}
  return response.json();
}
async function init(){try{
  applyConfig();
  const data=await Promise.all(config.dataFiles.map(file=>readJson(file)));
  bank=data.flat();
  if(!bank.length)throw new Error('Question bank is empty');
  profiles=await readJson(config.profilesFile,true);
  try{portraitIds=await readJson(config.portraitsFile,true);}catch{portraitIds=[];}
  if(!profiles.length)guideTab='terms';
  let raw;try{raw=localStorage.getItem(KEY);}catch{storageAvailable=false;}
  if(raw){try{const value=JSON.parse(raw);if(validProgress(value,new Set(bank.map(q=>q.id)),{categories:categoryIds}))progress=value;else toast('The saved progress format could not be read. Starting a fresh session.');}catch{toast('Saved progress could not be read. Starting a fresh session.');}}
  home();if(!storageAvailable)toast('Browser storage is unavailable; use Export progress to keep your learning history.');
}catch(err){mount(`<div class="loading"><span class="eyebrow orange">A BRIEF INTERRUPTION</span><h1>The briefing couldn’t load.</h1><p>Check your connection and refresh the page.</p><button class="btn primary" id="retry-load">Try again</button></div>`,'error');$('#retry-load').addEventListener('click',init);}}
init();
